window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[263]={"id":"263","numero":263,"titre":"Néphropathies vasculaires","objectifs":[{"id":"263-1","rang":"A","rubrique":"Définition","titre":"Connaître les différents types de néphropathies vasculaires","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1,"liens":[{"href":"https://manuel4.cuen.fr/spip.php","label":"manuel4.cuen.fr"}]},{"id":"263-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome de microangiopathie thrombotique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"263-3","rang":"B","rubrique":"Étiologies","titre":"Connaître les causes de microangiopathie thrombotique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/thrombotic-thrombocytopenic-purpura","label":"radiopaedia.org"}]},{"id":"263-4","rang":"B","rubrique":"Définition","titre":"Connaître la définition du syndrome hémolytique et urémique (SHU)","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"263-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic du SHU typique","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"263-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer le diagnostic de sténose de l'artère rénale","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"263-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les deux principales causes de sténose de l'artère rénale","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":1},{"id":"263-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique d'une sténose de l'artère rénale","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/renal-artery-stenosis","label":"radiopaedia.org"}]},{"id":"263-9","rang":"A","rubrique":"Définition","titre":"Connaître l'infarctus rénal, la sténose de l'artère rénale, la néphroangiosclérose bénigne, la maladie des emboles de cristaux de cholestérol","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":2},{"id":"263-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic de l'infarctus rénal, de la néphroangiosclérose bénigne, de la maladie des emboles de cristaux de cholestérol","contenu":"<p class=\"italic text-muted-foreground\">À compléter — objectif listé dans la trame officielle EDN, contenu à rédiger depuis <span class=\"kw-clinique\">les</span> fiches sources.</p>","frequence":7,"liens":[{"href":"https://radiopaedia.org/articles/renal-infarction","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/fat-embolism-syndrome","label":"radiopaedia.org"}]}],"astuces":[],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Néphropathie vasculaire suspectée — HTA et/ou insuffisance rénale au premier plan — éliminer d’abord un syndrome de MAT","detail":"<h4>CAT — orientation devant une néphropathie vasculaire — <span class=\"kw-etio\">HTA</span> et/ou IRA au premier plan : MAT (SHU/PTT) ou atteinte d’un vaisseau rénal ?</h4>","branches":[{"to":"q-mat","label":"Syndrome biologique de MAT : anémie hémolytique mécanique (schizocytes) + thrombopénie de consommation","color":"red"},{"to":"q-vasc","label":"Pas de MAT — atteinte d’un vaisseau rénal (gros tronc, artériole ou microcirculation)","color":"blue"}]},{"id":"q-mat","kind":"decision","label":"Microangiopathie thrombotique — orientation étiologique — Terrain · contexte digestif · organe au 1er plan","branches":[{"to":"t-shu-typique","label":"Enfant + diarrhée glairo-sanglante récente (été)","color":"amber"},{"to":"t-ptt","label":"Adulte + atteinte cérébrale au 1er plan, rein peu/pas touché","color":"red"},{"to":"t-shu-atypique","label":"Adulte + IRA-HTA, sans diarrhée préalable","color":"red"}]},{"id":"t-shu-typique","kind":"terminal","label":"SHU typique post-diarrhéique","color":"amber","detail":"<h4><span class=\"kw-def\">Terrain</span> & contexte</h4><ul><li>1ʳᵉ cause d’IRA chez l’enfant de <span class=\"kw-chiffre\">1 à 3 ans</span> ; <span class=\"kw-chiffre\">~90 %</span> des SHU de l’enfant</li><li><span class=\"kw-alerte\">Diarrhée glairo-sanglante</span> récente ; entérobactéries à <span class=\"kw-alerte\">Shiga-like toxins</span> (<span class=\"kw-etio\">E. coli O157:H7</span>)</li></ul><h4>Diagnostic</h4><ul><li>Triade : <span class=\"kw-bio\">anémie hémolytique mécanique</span> (<span class=\"kw-alerte\">schizocytes &gt; 2 %</span>, Coombs négatif) · <span class=\"kw-bio\">thrombopénie de consommation</span> · <span class=\"kw-clinique\">IRA organique</span></li><li><span class=\"kw-bio\">PCR sur selles</span> (gène de la toxine) ; <span class=\"kw-ci\">biopsie rénale inutile chez l’enfant</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique</span> : euvolémie, contrôle de l’<span class=\"kw-clinique\">HTA</span>, troubles hydro-électrolytiques</li><li><span class=\"kw-ttt\">Dialyse</span> si oligo-anurie / <span class=\"kw-bio\">hyperkaliémie</span> / surcharge ; <span class=\"kw-ci\">pas de ralentisseurs du transit</span></li></ul><h4>Renvoi</h4><ul><li>Item 286 (<span class=\"kw-clinique\">Diarrhée</span> aiguë infectieuse / TIAC) · Item 264 (IRA)</li></ul>"},{"id":"t-ptt","kind":"terminal","label":"PTT (syndrome de Moschowitz)","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span> & mécanisme</h4><ul><li><span class=\"kw-clinique\">Adulte</span> ; déficit en <span class=\"kw-bio\">ADAMTS13</span> (auto-AC le plus souvent)</li><li><span class=\"kw-alerte\">Atteinte cérébrale au 1ᵉʳ plan</span> ; atteinte rénale absente ou modérée</li></ul><h4>Diagnostic</h4><ul><li>Activité <span class=\"kw-bio\">ADAMTS13 &lt; 5-10 %</span> ; recherche d’<span class=\"kw-bio\">AC anti-ADAMTS13</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Urgence</span> : <span class=\"kw-ttt\">échanges plasmatiques</span> + <span class=\"kw-ttt\">plasma frais congelé</span> ± <span class=\"kw-ttt\">rituximab</span></li><li><span class=\"kw-ci\">Pas de transfusion de plaquettes</span> (risque d’aggravation)</li></ul><h4>Renvoi</h4><ul><li>Item 214 (Thrombopénie) · Item 215 (<span class=\"kw-clinique\">Purpura</span>)</li></ul>"},{"id":"t-shu-atypique","kind":"terminal","label":"SHU atypique (complément)","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span> & cause</h4><ul><li><span class=\"kw-clinique\">Adulte</span>, <span class=\"kw-alerte\">sans diarrhée</span> ; anomalie de la <span class=\"kw-bio\">voie alterne du complément</span></li><li>Mutations <span class=\"kw-bio\">C3 / facteur H / facteur I / CD46</span> · <span class=\"kw-bio\">AC anti-facteur H</span> · mutation de la <span class=\"kw-bio\">thrombomoduline</span></li></ul><h4>Présentation rénale</h4><ul><li><span class=\"kw-clinique\">IRA</span> + <span class=\"kw-clinique\">HTA</span> + souvent <span class=\"kw-clinique\">hématurie</span> et <span class=\"kw-clinique\">protéinurie</span> au 1ᵉʳ plan</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Échanges plasmatiques</span> + <span class=\"kw-ttt\">anti-C5</span> (<span class=\"kw-ttt\">eculizumab</span>, <span class=\"kw-ttt\">ravulizumab</span>)</li></ul><h4><span class=\"kw-def\">Pronostic</span></h4><ul><li><span class=\"kw-alerte\">Récidive élevée, y compris après transplantation</span> ; <span class=\"kw-def\">pronostic</span> rénal mauvais</li></ul><h4>Renvoi</h4><ul><li>Item 201 (Transplantation rénale) · Item 264 (IRA)</li></ul>"},{"id":"q-vasc","kind":"decision","label":"Atteinte vasculaire rénale — mode de présentation — Aigu vs chronique · calibre du vaisseau","branches":[{"to":"t-infarctus","label":"Douleur lombaire brutale + LDH élevés + hématurie (occlusion aiguë)","color":"red"},{"to":"t-emboles","label":"Geste vasculaire récent + orteils pourpres à pouls conservés + hyperéosinophilie","color":"amber"},{"to":"t-stenose","label":"HTA atypique (jeune / résistante / dégradation sous IEC-ARA2) + souffle abdominal","color":"amber"},{"to":"t-nas","label":"HTA ancienne mal contrôlée + syndrome urinaire pauvre + reins symétriques harmonieux","color":"blue"}]},{"id":"t-infarctus","kind":"terminal","label":"Infarctus rénal","color":"red","detail":"<h4>Causes</h4><ul><li><span class=\"kw-alerte\">Occlusion aiguë</span> d’une/des artères rénales : <span class=\"kw-etio\">dissection</span>, <span class=\"kw-etio\">thrombose in situ</span>, <span class=\"kw-etio\">embolie</span> (FA, valve mécanique, PAN macroscopique)</li></ul><h4>Clinique & biologie</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> + <span class=\"kw-clinique\">poussée</span> <span class=\"kw-clinique\">HTA</span> + <span class=\"kw-clinique\">hématurie macroscopique</span> + <span class=\"kw-clinique\">douleur lombaire</span> (mime la colique néphrétique) ; <span class=\"kw-alerte\">anurie</span> si bilatéral / rein unique</li><li><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">inflammatoire</span></span> · <span class=\"kw-bio\">créatininémie ↑</span> · <span class=\"kw-alerte\">LDH ↑</span></li></ul><h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">TDM spiralée</span>, <span class=\"kw-imagerie\">angio-IRM</span>, <span class=\"kw-imagerie\">artériographie</span> (échodoppler parfois)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Urgence thérapeutique</span> : <span class=\"kw-ttt\">revascularisation</span> (<span class=\"kw-ttt\">angioplastie</span> ou <span class=\"kw-ttt\">chirurgie</span>) seulement <span class=\"kw-chiffre\">&lt; 6 h</span> ; alternatives <span class=\"kw-ttt\">fibrinolytiques</span> / <span class=\"kw-ttt\">anticoagulants</span></li></ul><h4>Renvoi</h4><ul><li>Item 264 (IRA) · Item 193 (Vascularites — PAN)</li></ul>"},{"id":"t-emboles","kind":"terminal","label":"Emboles de cristaux de cholestérol","color":"amber","detail":"<h4><span class=\"kw-def\">Terrain</span> & déclencheurs</h4><ul><li><span class=\"kw-def\">Terrain</span> <span class=\"kw-etio\">athéromateux</span> ; déclenché par <span class=\"kw-clinique\">chirurgie aortique</span>, <span class=\"kw-clinique\">artériographie</span>, <span class=\"kw-ttt\">anticoagulants</span> ; signes décalés de <span class=\"kw-chiffre\">jours-semaines</span></li></ul><h4>Manifestations</h4><ul><li><span class=\"kw-alerte\">Orteils pourpres douloureux à pouls conservés</span> (<span class=\"kw-clinique\">syndrome de l</span>’orteil bleu), <span class=\"kw-clinique\">livedo</span>, <span class=\"kw-clinique\">gangrène</span> distale</li><li><span class=\"kw-clinique\">IRA</span>, ischémie mésentérique, troubles visuels, signes neurologiques</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-clinique\">Syndrome <span class=\"kw-etio\">inflammatoire</span></span>, <span class=\"kw-clinique\">IRA</span> ; inconstants : <span class=\"kw-bio\">hyperéosinophilie</span>, <span class=\"kw-bio\">hypocomplémentémie</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Arrêt des anticoagulants</span> · <span class=\"kw-ci\">contre-indication des gestes intravasculaires</span></li><li>Contrôle de l’<span class=\"kw-clinique\">HTA</span> et des <span class=\"kw-etio\">FRCV</span>, <span class=\"kw-ttt\">dialyse</span>, <span class=\"kw-ttt\">corticothérapie</span> parfois ; <span class=\"kw-def\">mortalité</span> <span class=\"kw-alerte\">&gt; 40 % à 6 mois</span></li></ul><h4>Renvoi</h4><ul><li>Item 222 (<span class=\"kw-etio\">Athérome</span> / <span class=\"kw-etio\">FRCV</span>) · Item 264 (IRA)</li></ul>"},{"id":"t-stenose","kind":"terminal","label":"Sténose de l’artère rénale","color":"amber","detail":"<h4>Quand l’évoquer</h4><ul><li><span class=\"kw-alerte\">HTA &lt; 30 ans</span> (dysplasie), <span class=\"kw-alerte\">HTA résistante</span> à une <span class=\"kw-ttt\">trithérapie</span>, <span class=\"kw-clinique\">souffle abdominal latéralisé</span>, <span class=\"kw-alerte\">OAP flash</span>, <span class=\"kw-alerte\">aggravation de l’IRA sous IEC/ARA2</span></li></ul><h4>Deux causes</h4><ul><li><span class=\"kw-etio\">Athéromateuse</span> (<span class=\"kw-chiffre\">90 %</span>) : homme &gt;<span class=\"kw-chiffre\"> 45 ans</span>, 1/3 proximal</li><li><span class=\"kw-etio\">Fibrodysplasique</span> (<span class=\"kw-chiffre\">10 %</span>) : femme <span class=\"kw-chiffre\">25-40 ans</span>, 2/3 distaux, « collier de perles »</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Angio-TDM / angio-IRM</span> en <span class=\"kw-chiffre\">1ʳᵉ intention</span> ; <span class=\"kw-imagerie\">artériographie</span> (gold-standard) seulement si <span class=\"kw-ttt\">revascularisation</span></li></ul><h4>Traitement</h4><ul><li>Athéromateuse : <span class=\"kw-etio\">FRCV</span> + <span class=\"kw-ttt\">IEC/ARA2</span> (<span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">créat/kaliémie</span>) ; <span class=\"kw-ci\">IEC/ARA2 CI si sténose bilatérale ou rein unique</span> ; <span class=\"kw-ttt\">revascularisation</span> non systématique</li><li>Fibrodysplasique : <span class=\"kw-ttt\">angioplastie transluminale</span> (curative, <span class=\"kw-etio\">HTA</span> améliorée <span class=\"kw-chiffre\">70-90 %</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 224 (<span class=\"kw-etio\">HTA</span> secondaire) · Item 330 (Médicaments du SRAA)</li></ul>"},{"id":"t-nas","kind":"terminal","label":"Néphroangiosclérose bénigne","color":"blue","detail":"<h4>Cause & <span class=\"kw-def\">terrain</span></h4><ul><li>Conséquence d’une <span class=\"kw-alerte\">HTA ancienne mal contrôlée</span> ; <span class=\"kw-def\">endartérite fibreuse</span> ; <span class=\"kw-alerte\">2ᵉ cause d’IRT</span></li></ul><h4>Clinique & biologie</h4><ul><li><span class=\"kw-clinique\">Syndrome urinaire pauvre</span> (pas d’<span class=\"kw-bio\">hématurie</span>/<span class=\"kw-bio\">leucocyturie</span>, <span class=\"kw-bio\">protéinurie</span> absente ou modérée)</li><li><span class=\"kw-bio\">Micro-albuminurie &gt; 30 mg/24 h</span> = signe précoce ; IRC lentement progressive</li></ul><h4>Imagerie</h4><ul><li>Reins <span class=\"kw-clinique\">symétriques, contours harmonieux</span> ; <span class=\"kw-ci\">pas de sténose des artères rénales</span></li></ul><h4>Traitement</h4><ul><li>Contrôle des <span class=\"kw-etio\">FRCV</span> + traitement de l’<span class=\"kw-clinique\">HTA</span> (<span class=\"kw-ttt\">IEC</span> si <span class=\"kw-bio\">albuminurie</span>) ; objectifs <span class=\"kw-chiffre\">PA &lt; 130/80</span> si <span class=\"kw-bio\">albuminurie</span> <span class=\"kw-chiffre\">≥ 30 mg</span>/<span class=\"kw-chiffre\">24 h</span>, sinon <span class=\"kw-chiffre\">&lt; 140/90</span></li></ul><h4>Renvoi</h4><ul><li>Item 224 (<span class=\"kw-etio\">HTA</span>) · Item 264 (IRC/IRT)</li></ul>"}]},"cards":[]};